const test = require('node:test');
const assert = require('node:assert/strict');
const { parseRequest } = require('../request');
const { routeRequest } = require('../router');
const parse = (text) => parseRequest(Buffer.from(text, 'latin1'));

test('reads request line, case-insensitive headers and binary body', () => {
  const request = parse('POST /echo HTTP/1.1
Content-Length: 3
X-Test: value

a\x00b');
  assert.equal(request.method, 'POST');
  assert.equal(request.path, '/echo');
  assert.equal(request.headers['x-test'], 'value');
  assert.deepEqual(request.body, Buffer.from([97, 0, 98]));
  assert.match(routeRequest(request), /

POST /echo$/);
});

test('waits for headers and complete body at every chunk boundary', () => {
  const text = 'POST /echo HTTP/1.1
Content-Length: 4

test';
  for (let i = 0; i < text.length; i++) assert.equal(parse(text.slice(0, i)), null);
  assert.equal(parse(text).body.toString(), 'test');
});

test('accepts empty headers and preserves existing routes', () => {
  assert.equal(parse('GET / HTTP/1.1

').body.length, 0);
  assert.match(routeRequest(parse('GET / HTTP/1.1

')), /200 OK/);
  assert.match(routeRequest(parse('GET /users/1/posts/2 HTTP/1.1

')), /

1 2$/);
  assert.match(routeRequest(parse('POST / HTTP/1.1

')), /405 Method Not Allowed/);
  assert.match(routeRequest(parse('GET /missing HTTP/1.1

')), /404 Not Found/);
});

test('rejects malformed requests and ambiguous framing', () => {
  for (const text of [
    'GET / INVALID

',
    'GET  / HTTP/1.1

',
    'GET / HTTP/1.1
Broken

',
    'GET / HTTP/1.1
Bad Name: x

',
    'GET / HTTP/1.1
Content-Length: -1

',
    'GET / HTTP/1.1
Content-Length: 2x

',
    'GET / HTTP/1.1
Content-Length: 0
content-length: 0

',
    'GET / HTTP/1.1
Transfer-Encoding: chunked

',
  ]) assert.throws(() => parse(text));
  assert.throws(() => parseRequest(Buffer.from('GET / HTTP/1.1

'), 8));
});

